    def topf(H): return f'[[fig:top:{spec(H)}]]'
    def viewQ(qid, diff, H, side, text=None):
        cols = front(H) if side == 'front' else right(H)
        ans = vw(cols)
        cands = [(vw(cols[::-1]), 'dir') if cols[::-1] != cols else None,
                 (vw(H[-1] if side == 'front' else [r[-1] for r in reversed(H)]), 'row'),
                 (vw(H[0] if side == 'front' else [r[0] for r in reversed(H)]), 'row'),
                 (vw([sum(H[j][i] for j in range(len(H))) for i in range(len(H[0]))] if side == 'front' else [sum(r) for r in reversed(H)]), 'sum') if max(sum(H[j][i] for j in range(len(H))) for i in range(len(H[0]))) <= 5 else None,
                 (vw(right(H) if side == 'front' else front(H)), 'dir'), (vw([1] * len(cols)), 'top'), (vw([max(cols)] * len(cols)), 'row')]
        cands = [c for c in cands if c and c[0] != ans]
        word = '앞' if side == 'front' else '오른쪽 옆'
        t = text or f'{topf(H)} 쌓기나무로 쌓은 모양을 위에서 본 모양에 수를 썼습니다. {word}에서 본 모양은 어느 것일까요?'
        h2 = '세로줄마다 가장 큰 수를 찾아요.' if side == 'front' else '오른쪽에서 보면 앞쪽 줄이 왼쪽에 보여요. 줄마다 가장 큰 수를 찾아요.'
        return Q(b, qid, diff, t, ans, cands, H2, h2, f'{word}에서 보면 줄마다 가장 높은 기둥이 보여요: ' + ', '.join(map(str, cols)) + '층.',
                 '첫 단계: 보는 쪽에서 보이는 줄을 차례로 정해요', {'view': side, 'top': spec(H), 'cols': cols})

